// Dua kemungkinan input: daftar sesi (n8n memecah array jadi banyak item) ATAU item error (WAHA tak terjangkau).
const items = $input.all().map((i) => i.json);

let status;
if (items.length && items[0] && items[0].error) {
  status = 'TIDAK_TERJANGKAU';
} else {
  const sesi = items.find((x) => x && x.name === 'default');
  status = sesi ? String(sesi.status || 'TIDAK_DIKETAHUI') : 'SESI_TIDAK_ADA';
}

const bermasalah = status !== 'WORKING';

// Anti-spam: selama masih down, alert maksimal 1× per 60 menit; reset saat pulih.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
let kirim = false;
if (!bermasalah) {
  sd.lastAlertAt = 0;
} else if (!sd.lastAlertAt || now - sd.lastAlertAt > 60 * 60 * 1000) {
  kirim = true;
  sd.lastAlertAt = now;
}

const waktu = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', hour12: false });

// Email — template 8b docs/copywriting-pesan.md (via EMAIL karena kanal WA-nya yang mati)
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#333;line-height:1.6">
<p>Status sesi WAHA: <strong>${status}</strong> (bukan WORKING) — terdeteksi ${waktu} WIB.</p>
<p><strong>Dampak:</strong> semua pengiriman WA berhenti; email tetap berjalan. Order tetap diproses.</p>
<p><strong>Tindakan:</strong> SSH ke VPS → <code>ssh -L 3000:127.0.0.1:3000 root@31.97.50.197</code> → buka <code>http://localhost:3000/dashboard</code> → login (user <code>harih</code>) → restart / scan ulang QR sesi <code>default</code>.</p>
<p>Setelah pulih, cek kolom <code>wa_status</code> di sheet <code>orders</code> untuk pesan yang perlu dikirim ulang.</p>
</div>`;

const emailPayload = {
  sender: { name: $env.BREVO_SENDER_NAME || 'hariH', email: $env.BREVO_SENDER_EMAIL },
  to: [{ email: $env.OWNER_EMAIL }],
  subject: '🚨 [hariH] Sesi WhatsApp DOWN — delivery WA berhenti',
  htmlContent: html,
};

return [{ json: { status, kirim, email_payload: emailPayload } }];
